import{_ as o,c as l,j as n,a,o as t}from"./chunks/framework.Bzjhwp8w.js";const m=JSON.parse('{"title":"4 Conclusion","description":"","frontmatter":{},"headers":[],"relativePath":"scientist_AI/7_4_conclusion.md","filePath":"scientist_AI/7_4_conclusion.md"}'),i={name:"scientist_AI/7_4_conclusion.md"};function s(c,e,r,A,_,d){return t(),l("div",null,e[0]||(e[0]=[n("h1",{id:"_4-conclusion",tabindex:"-1"},[a("4 Conclusion "),n("a",{class:"header-anchor",href:"#_4-conclusion","aria-label":'Permalink to "4 Conclusion"'},"​")],-1),n("p",null,"今天的前沿 AI 是越来越有能力的通用智能体。这些技术奇迹无疑很有用，但它们也在快速发展关键能力，如欺骗 (§2.3.1)、说服 (§2.3.2)、长期计划 (§2.3.4) 和技术网络安全敏锐性 (§2.3.3)，这可能导致巨大的基础设施和机构损害，尤其是在我们与它们发生冲突时。不幸的是，智能体天生会选择自我保护 (§2.2.1)，而强大的自我保护智能体在现实世界中的行为往往与人类利益 (§2.2.2) 直接冲突，迫使我们认真考虑灾难性风险的可能性。",-1),n("p",null,"实际上，这些风险源于用于训练当前前沿 AI 系统的方法。强化学习，作为训练智能体以最大化长期累积奖励的标准实践，容易导致目标误设和错误概括 (§2.4)。特别是，我们必须承认，通用智能体在无边界环境中操作时，可以通过控制奖励机制最大化其奖励，而不是真正实现预期的目标 (§2.4.4 和 §2.4.5)。另一种思路是我们训练 AI 模拟人类行为，但不是为了清晰：此类系统将继承并可能放大人类智能的不良方面 (§2.5.1)——毕竟，我们全都是通用智能体。多于几个拥有有限能力的人可能对人类构成严重威胁，而注入具有迫在眉睫认知能力的类人心智可能同样有问题 (§2.5.3)。由于前沿 AI 系统在最后训练阶段更倾向于奉承而不是讲真话，他们似乎倾向于假装与用户的目标一致，只是为了被接受 (§2.5.2)。这使它们难以信任。",-1),n("p",null,"减轻这些风险的一种显著方法是，解决构建较不通用并部署在限域场景的 AI 系统 (§3.2.2)。我们相信，这也许是一种方式，使我们能够从通用 AI 系统的巨大潜能中获益，而不会发生灾难性的风险——只要我们不用它来追求自身目标。换句话说，我们对一种非代理系统感兴趣，不是因为它缺乏通用智能，而是因为它缺乏我们定义的两大核心支柱 (§3.2): 可操作性和目标导向性。",-1),n("p",null,"我们的研究计划 (§3) 奠定了创建科学家 AI 的基础: 一个安全、可信的非代理系统。这种命名来源于一个常见的科学模式：首先努力理解世界，然后基于这种理解做出推断。为了模拟这些步骤，我们使用一个世界模型 (§3.4)，这个模型基于理论推导来解释世界，一个推论机器 (§3.5) 用来解答基于那些理论的问题。这些组件是贝叶斯的，并以校准的概率方式处理不确定性 (§3.3) 以防止过度自信。因为我们也生成可解释的理论，并仔细区分言论及其含义，我们认为其结果是可解释的 (§3.6)。科学家 AI 本身是非代理的设计，我们也概述了对意外方式中代理行为的防范战略 (§3.7)。此外，科学家 AI 享有至关重要的收敛性: 数据和计算能力的增长提供了在性能和安全性上的改善，使我们的系统区别于当前的训练模式 (§2.2.5)。原则上，科学家 AI 可用于帮助人类研究者加速科学进步 (§3.8.1)，包括 AI 安全。在特别情况下，我们为其在更具代理能力的 AI 系统周围作为守护的应用铺平了道路 (§3.8.2)。最终，专注于非代理 AI 可以在避免当前轨迹风险的情况下实现 AI 创新的好处。我们希望这些论点能激励研究人员、开发人员和政策制定者专注于尚未完全形成代理的通用 AI 系统的开发。",-1),n("h2",{id:"acknowledgments",tabindex:"-1"},[a("Acknowledgments "),n("a",{class:"header-anchor",href:"#acknowledgments","aria-label":'Permalink to "Acknowledgments"'},"​")],-1),n("p",null,"感谢 Ouamaima Amzegar、Shahar Avin、Alan Chan、Can (Sam) Chen、Xiaoyin Chen、Jean-Pierre Falet、Kaarel Hännì、Moksh Jain、Daniel Privitera 和 Tianyu Zhang 对本文的反馈和改进。",-1)]))}const I=o(i,[["render",s]]);export{m as __pageData,I as default};
